import sys
sys.setrecursionlimit(300000)

def main():
    input = sys.stdin.read
    data = input().split()
    idx = 0

    n = int(data[idx])
    idx += 1

    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = int(data[idx])
        v = int(data[idx + 1])
        idx += 2
        adj[u].append(v)
        adj[v].append(u)

    parent = [0] * (n + 1)
    depth = [0] * (n + 1)
    up = [[0] * 20 for _ in range(n + 1)]

    def dfs(u, p, d):
        parent[u] = p
        depth[u] = d
        up[u][0] = p
        for i in range(1, 20):
            up[u][i] = up[up[u][i - 1]][i - 1]
        for v in adj[u]:
            if v != p:
                dfs(v, u, d + 1)

    dfs(1, 1, 0)

    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        diff = depth[u] - depth[v]
        for i in range(20):
            if diff & (1 << i):
                u = up[u][i]
        if u == v:
            return u
        for i in range(19, -1, -1):
            if up[u][i] != up[v][i]:
                u = up[u][i]
                v = up[v][i]
        return up[u][0]

    def dist(u, v):
        return depth[u] + depth[v] - 2 * depth[lca(u, v)]

    def kth_ancestor(u, k):
        for i in range(20):
            if k & (1 << i):
                u = up[u][i] if up[u][i] != 0 else u
        return u

    def get_path_nodes(u, v):
        l = lca(u, v)
        nodes = []
        curr = u
        while curr != l:
            nodes.append(curr)
            curr = parent[curr]
        nodes.append(l)
        temp = []
        curr = v
        while curr != l:
            temp.append(curr)
            curr = parent[curr]
        temp.reverse()
        nodes.extend(temp)
        return nodes

    t = int(data[idx])
    idx += 1

    results = []

    for _ in range(t):
        u = int(data[idx])
        v = int(data[int(idx + 1)])
        x = int(data[idx + 2])
        y = int(data[idx + 3])
        idx += 4

        if u == x:
            results.append("0")
            continue

        path_uv = get_path_nodes(u, v)
        path_xy = get_path_nodes(x, y)

        set_uv = set(path_uv)
        set_xy = set(path_xy)

        common = set_uv & set_xy
        if not common:
            results.append("-1")
            continue

        len_uv = len(path_uv)
        len_xy = len(path_xy)

        pos_uv = {node: i for i, node in enumerate(path_uv)}
        pos_xy = {node: i for i, node in enumerate(path_xy)}

        min_time = float('inf')

        for node in common:
            i = pos_uv[node]
            j = pos_xy[node]

            period_uv = 2 * (len_uv - 1)
            period_xy = 2 * (len_xy - 1)

            t1 = i
            t2 = j

            for cycle_u in range(period_uv):
                time_u = t1 + cycle_u * period_uv
                if time_u > min_time:
                    break

                target = (time_u - t2) % period_xy
                if target < 0:
                    target += period_xy
                if target >= period_xy:
                    continue

                time_v = t2 + target
                if time_v < time_u:
                    time_v += period_xy * ((time_u - time_v + period_xy - 1) // period_xy)

                if time_v == time_u:
                    if time_u < min_time:
                        min_time = time_u
                elif time_v > time_u:
                    diff = time_v - time_u
                    if diff % period_uv == 0:
                        new_time = time_v
                        if new_time < min_time:
                            min_time = new_time

        if min_time == float('inf'):
            results.append("-1")
        else:
            results.append(str(min_time))

    print('\n'.join(results))

if __name__ == "__main__":
    main()
